// This file was generated by Prisma, and assumes you have installed the following:
// npm install --save-dev prisma dotenv
// Load env the same way Next.js does: .env.local overrides .env (first match
// wins, dotenv never overrides vars already in process.env). This keeps the
// Prisma CLI (db push / generate) in sync with the app, and is safe on Vercel
// where no .env* file exists and the real DATABASE_URL is already in the env.
import { config } from "dotenv";
config({ path: [".env.local", ".env"] });
import { defineConfig } from "prisma/config";

export default defineConfig({
  schema: "prisma/schema.prisma",
  migrations: {
    path: "prisma/migrations",
  },
  datasource: {
    url: process.env["DATABASE_URL"],
  },
});
